#!/usr/bin/env python3
"""The test_controller_rework tests were split (TD-11c): the parts hold the checks and controller_rework_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_controller_rework.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from controller_rework_common import (  # noqa: E402,F401
    AUTOMATOR,
    WORDS,
    at_s5,
    designer_story,
    host_receipt,
    redo,
    refusal,
    settle,
    story_to_s8,
    words_file,
)

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["AUTOMATOR", "WORDS", "at_s5", "designer_story", "host_receipt", "redo", "refusal", "settle", "story_to_s8", "words_file"]

PARTS = ("test_controller_rework_jobs_guard", "test_controller_rework_repair_binding", "test_controller_rework_window_words")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_controller_rework.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
